SCRIPT       : [MyMod] MyMod_Crate OnStoreLoad: ctx.Read(m_Locked) failed

File scripts/4_World/MyMod/mymod_crate.c:

class MyMod_Crate extends WoodenCrate
{
    int m_Charges;
    bool m_Locked;

    override void OnStoreSave(ParamsWriteContext ctx)
    {
        super.OnStoreSave(ctx);
        ctx.Write(m_Charges);
    }

    override bool OnStoreLoad(ParamsReadContext ctx, int version)
    {
        if (!super.OnStoreLoad(ctx, version))
            return false;
        if (!ctx.Read(m_Charges))
            return false;
        if (!ctx.Read(m_Locked))
        {
            Print("[MyMod] MyMod_Crate OnStoreLoad: ctx.Read(m_Locked) failed");
            return false;
        }
        return true;
    }
}

Return your usual report.

